struct EntityBackupField {
  const char *key;           // entity_names.json key
  const char *entity_name;   // exact ESPHome entity name
  const char *domain;        // text | select | number | switch
  const char *section;       // root | settings | screen
  const char *field;         // envelope field name
  bool derived;              // needs a hand-written rule, not a plain write
};

