// Envelope fields with no entity of their own; resolved to `target` on import.
//
// `exported` marks an alias the browser's export literal also writes, so GET has
// to emit it as well as its target to stay envelope-compatible. An alias without
// it is inbound-only: accepted on write, never emitted on read.
struct EntityBackupAlias {
  const char *section;
  const char *field;
  const char *target;
  bool exported;
};

inline constexpr EntityBackupAlias ENTITY_BACKUP_ALIASES[] = {
    {"settings", "clock_brightness", "clock_brightness_day", true},
    {"settings", "cover_art_conditions", "cover_art_attribute_conditions", false},
};
inline constexpr size_t ENTITY_BACKUP_ALIAS_COUNT =
    sizeof(ENTITY_BACKUP_ALIASES) / sizeof(ENTITY_BACKUP_ALIASES[0]);

// Slot-templated config entities. Firmware discovers the device's slot and
// subpage-chunk counts by probing these names, so no per-device constant is
// needed for the 4-chunk vs 8-chunk profiles.
struct EntitySlotTemplate {
  const char *key;
  const char *name_prefix;
  const char *name_suffix;
};

